1	/**
2	 * ctxl — Self-Authoring React Component Library
3	 *
4	 * A runtime for LLM-embodied React components that author themselves on first
5	 * mount, reason about input changes via hooks, and can rewrite their own source.
6	 *
7	 * Usage as ES module:
8	 *   import { create } from './ctxl';
9	 *   const system = await create({ target: el, apiMode: 'proxy' });
10	 *
11	 * Usage with React provider (recommended for existing apps):
12	 *   import { CtxlProvider } from './ctxl';
13	 *   <CtxlProvider apiMode="proxy">
14	 *     <AbstractComponent id="chat" inputs={{ topic: "React" }} />
15	 *   </CtxlProvider>
16	 *
17	 * Usage as script:
18	 *   <script type="module">
19	 *     const { create } = await import('./src/ctxl.js');
20	 *     await create({ target: document.getElementById('root'), apiMode: 'proxy' });
21	 *   </script>
22	 *
23	 * Requirements — the host page must include an import map for the VFS runtime:
24	 *   react, react/jsx-runtime, react-dom/client, react-refresh/runtime, styled-components
25	 */
26	import type { CreateOptions, CreateResult } from "./types";
27	
28	// Re-export all primitives
29	export { createIDB } from "./idb";
30	export { injectReactRefresh } from "./refresh";
31	export { createVFSPlugin } from "./vfs-plugin";
32	export { createAtomRegistry } from "./atoms";
33	export { callLLM, extractText, extractToolUse } from "./llm";
34	export { buildAuthoringPrompt, buildReasoningContext } from "./prompts";
35	export { createRuntime } from "./runtime";
36	export { SEEDS } from "./seeds-v2";
37	
38	// Shared init (used by CtxlProvider and boot.ts)
39	export { initSystem } from "./init";
40	export type { InitSystemOptions, InitSystemResult } from "./init";
41	
42	// React provider for library consumers
43	export { CtxlProvider, useCtxlRuntime, HostRuntimeContext } from "./context";
44	export type { CtxlProviderProps, RuntimeContextValue } from "./context";
45	
46	// Re-export types
47	export type {
48	  IDB,
49	  VFSRow,
50	  RuntimeConfig,
51	  ApiMode,
52	  RuntimeCallbacks,
53	  FilePatch,
54	  EsbuildPlugin,
55	  Esbuild,
56	  Runtime,
57	  RuntimeOptions,
58	  CreateOptions,
59	  CreateResult,
60	  ToolDef,
61	  UseReasoningReturn,
62	  ReasoningResult,
63	  MutationRecord,
64	} from "./types";
65	
66	// Imports needed by create()
67	import { initSystem } from "./init";
68	import { createRuntime } from "./runtime";
69	import { createAtomRegistry } from "./atoms";
70	import { createIDB } from "./idb";
71	import { SEEDS } from "./seeds-v2";
72	
73	/**
74	 * High-level API: create and boot a complete system.
75	 *
76	 * Uses the same initSystem() code path as <CtxlProvider>,
77	 * then triggers the first buildAndRun.
78	 */
79	export async function create(options: CreateOptions = {}): Promise<CreateResult> {
80	  const { target, callbacks = {}, ...rest } = options;
81	
82	  // Ensure target element
83	  if (target && !target.id) target.id = "root";
84	
85	  const { runtime, files, idb } = await initSystem({ callbacks, ...rest });
86	
87	  // Trigger first build
88	  await runtime.buildAndRun("create");
89	
90	  return { runtime, files, idb };
91	}
92	
93	// Register on window for script-tag usage
94	if (typeof window !== "undefined") {
95	  window.ctxl = { create, createRuntime, createAtomRegistry, createIDB, SEEDS };
96	}
