65	// ---- Runtime ----
66	
67	export interface Runtime {
68	  files: Map<string, string>;
69	  disposers: Array<() => void>;
70	  config: RuntimeConfig;
71	  RefreshRuntime: any;
72	  idb: IDB;
73	
74	  // Config
75	  saveConfig(): void;
76	
77	  // v2: Unified LLM transport
78	  callLLM(system: string, messages: Array<{ role: string; content: any }>, extras?: Record<string, any>): Promise<any>;
79	
80	  // v2: Authoring
81	  buildAuthoringPrompt(componentId: string, inputs: Record<string, any>, tools: ToolDef[], handlers?: Record<string, string>, guidelines?: string, existingSource?: string): string;
82	  regenerateRegistry(): void;
83	
84	  // Build pipeline
85	  applyPatch(patches: FilePatch[]): Promise<void>;
86	  runDisposers(): void;
87	  buildBundle(entry?: string): Promise<{ code: string; ms: number }>;
88	  importBundle(code: string): Promise<unknown>;
89	  buildAndRun(reason?: string): Promise<void>;
90	
91	  // Init
