97	// ---- Factory options ----
98	
99	export interface RuntimeOptions {
100	  esbuild: Esbuild;
101	  idb: IDB;
102	  files: Map<string, string>;
103	  config: RuntimeConfig;
104	  callbacks?: RuntimeCallbacks;
105	}
106	
107	// ---- Create API ----
108	
109	export interface CreateOptions {
110	  target?: HTMLElement;
111	  seeds?: Map<string, string>;
112	  apiMode?: ApiMode;
