609	// ---- useAtom ----
610	
611	/**
612	 * Subscribe to a shared state atom.
613	 * Atoms are created and managed by the host runtime.
614	 *
615	 * Usage:
616	 *   const [value, setValue] = useAtom("myKey", defaultValue);
617	 */
618	export function useAtom<T = any>(key: string, defaultValue?: T): [T, (v: T | ((prev: T) => T)) => void] {
619	  const { atoms: registry } = useRuntimeContext();
620	  if (!registry) {
621	    // Fallback: no atom registry, use local state
622	    const [val, setVal] = useState<T>(defaultValue as T);
623	    return [val, setVal];
624	  }
625	
626	  // Ensure atom exists
627	  const atom = registry.create(key, defaultValue);
628	
629	  const value = useSyncExternalStore(
630	    (cb: () => void) => atom.subscribe(cb),
631	    () => atom.get(),
632	  );
633	
634	  const setValue = useCallback((v: T | ((prev: T) => T)) => {
635	    atom.set(v);
636	  }, [atom]);
637	
638	  return [value as T, setValue];
639	}
