1	/**
2	 * Atom store — scoped external state that survives self-modification.
3	 *
4	 * Each atom is a named piece of state with pub/sub semantics.
5	 * Atoms persist to IndexedDB and survive module reimports, React Refresh,
6	 * self-modification, and page reloads.
7	 *
8	 * Host-side module: creates atoms and manages the registry on window.__ATOMS__.
9	 * VFS components access atoms via the useAtom hook (src/seeds/ctxl/hooks.ts).
10	 */
11	import type { IDB } from "./types";
12	
13	export interface Atom<T = any> {
14	  key: string;
15	  defaultValue: T;
16	  _value: T;
17	  _listeners: Set<() => void>;
18	  get(): T;
19	  set(value: T | ((prev: T) => T)): void;
20	  subscribe(fn: () => void): () => void;
21	}
22	
23	export interface AtomRegistry {
24	  atoms: Map<string, Atom>;
25	  idb: IDB | null;
26	  create<T>(key: string, defaultValue: T): Atom<T>;
27	  get<T>(key: string): Atom<T> | undefined;
28	  hydrate(idb: IDB): Promise<void>;
29	}
30	
31	/** Persist atom value to IDB under the __atom: prefix. */
32	async function persistAtom(registry: AtomRegistry, key: string, value: any) {
33	  if (!registry.idb) return;
34	  try {
35	    await registry.idb.put(`__atom:${key}`, JSON.stringify(value));
36	  } catch (e) {
37	    console.warn("[atoms] persist failed for", key, e);
38	  }
39	}
40	
41	export function createAtomRegistry(): AtomRegistry {
42	  const registry: AtomRegistry = {
43	    atoms: new Map(),
44	    idb: null,
45	
46	    create<T>(key: string, defaultValue: T): Atom<T> {
47	      const existing = this.atoms.get(key);
48	      if (existing) return existing as Atom<T>;
49	
50	      const atom: Atom<T> = {
51	        key,
52	        defaultValue,
53	        _value: defaultValue,
54	        _listeners: new Set(),
55	        get() { return this._value; },
56	        set(valueOrFn: T | ((prev: T) => T)) {
57	          const next = typeof valueOrFn === "function"
58	            ? (valueOrFn as (prev: T) => T)(this._value)
59	            : valueOrFn;
60	          if (Object.is(this._value, next)) return;
61	          this._value = next;
62	          this._listeners.forEach(fn => fn());
63	          persistAtom(registry, key, next);
64	        },
65	        subscribe(fn: () => void) {
66	          this._listeners.add(fn);
67	          return () => { this._listeners.delete(fn); };
68	        },
69	      };
70	
71	      this.atoms.set(key, atom);
72	      return atom;
73	    },
74	
75	    get<T>(key: string): Atom<T> | undefined {
76	      return this.atoms.get(key) as Atom<T> | undefined;
77	    },
78	
79	    /** Load persisted atom values from IDB. */
80	    async hydrate(idb: IDB) {
81	      this.idb = idb;
82	      const rows = await idb.getAll();
83	      for (const row of rows) {
84	        if (!row.path.startsWith("__atom:")) continue;
85	        const key = row.path.slice("__atom:".length);
86	        try {
87	          const value = JSON.parse(row.text);
88	          const existing = this.atoms.get(key);
89	          if (existing) {
90	            existing._value = value;
91	          }
92	          // If atom hasn't been created yet, the value will be loaded
93	          // when create() is called — we store it speculatively.
94	          if (!existing) {
95	            // Stash for later hydration when atom is created
96	            (this as any)._pending ??= new Map();
97	            (this as any)._pending.set(key, value);
98	          }
99	        } catch { /* skip malformed */ }
100	      }
101	    },
102	  };
103	
104	  // Patch create to check pending hydration
105	  const originalCreate = registry.create.bind(registry);
106	  registry.create = function <T>(key: string, defaultValue: T): Atom<T> {
107	    const atom = originalCreate(key, defaultValue);
108	    const pending = (registry as any)._pending as Map<string, any> | undefined;
109	    if (pending?.has(key)) {
110	      atom._value = pending.get(key);
111	      pending.delete(key);
112	    }
113	    return atom;
114	  };
115	
116	  return registry;
117	}
