1	/**
2	 * CtxlProvider — Host-bundle React provider for library consumers.
3	 *
4	 * Wraps an existing React app so that <AbstractComponent>, useAtom, and
5	 * useReasoning work inside the tree without globals.
6	 *
7	 * Usage:
8	 *   import { CtxlProvider } from "ctxl";
9	 *
10	 *   function App() {
11	 *     return (
12	 *       <CtxlProvider apiMode="proxy" proxyUrl="/api/chat">
13	 *         <AbstractComponent id="chat" inputs={{ topic: "React" }} />
14	 *       </CtxlProvider>
15	 *     );
16	 *   }
17	 *
18	 * The provider handles the full async boot sequence (esbuild-wasm, IDB,
19	 * atom registry, runtime) via the shared initSystem() function — the same
20	 * code path that the dev environment's boot.ts uses.
21	 */
22	import React, { useEffect, useState, useRef, createContext, useContext } from "react";
23	import type { ReactNode } from "react";
24	import { initSystem } from "./init";
25	import type { InitSystemResult, InitSystemOptions } from "./init";
26	import type { RuntimeCallbacks, ApiMode } from "./types";
27	
28	// ---- Context (host-side mirror of the VFS RuntimeContext) ----
29	
30	export type RuntimeContextValue = InitSystemResult;
31	
32	/**
33	 * The context object.  In VFS-compiled code the identical shape is defined
34	 * in hooks.ts; both point at the same React.createContext instance when the
35	 * import-map shares a single React, so provider/consumer pairing works
36	 * across the host - blob-ESM boundary.
37	 *
38	 * For the host bundle we define our own createContext — the VFS side falls
39	 * back to globals when no provider is found, so there is no mismatch.
40	 */
41	export const HostRuntimeContext = createContext<RuntimeContextValue | null>(null);
42	
43	export function useCtxlRuntime(): RuntimeContextValue {
44	  const ctx = useContext(HostRuntimeContext);
45	  if (!ctx) throw new Error("useCtxlRuntime must be used within <CtxlProvider>");
46	  return ctx;
47	}
48	
49	// ---- Provider props ----
50	
51	export interface CtxlProviderProps {
52	  children: ReactNode;
53	  /** How the LLM is reached: "none" | "anthropic" | "proxy" */
54	  apiMode?: ApiMode;
55	  apiKey?: string;
56	  proxyUrl?: string;
57	  model?: string;
58	  /** URL for the esbuild-wasm ESM loader */
59	  esbuildUrl?: string;
60	  /** URL for the esbuild .wasm binary */
61	  esbuildWasmUrl?: string;
62	  /** IndexedDB database name */
63	  dbName?: string;
64	  /** Override the default VFS seed files */
65	  seeds?: Map<string, string>;
66	  /** Runtime lifecycle callbacks (status, build, errors) */
67	  callbacks?: RuntimeCallbacks;
68	  /** Rendered while the system is booting */
69	  fallback?: ReactNode;
70	  /**
71	   * If provided, the runtime + atoms are also written to window globals
72	   * for backward compatibility (window.__RUNTIME__, window.__ATOMS__).
73	   * Defaults to true.
74	   */
75	  exposeGlobals?: boolean;
76	}
77	
78	// ---- Provider ----
79	
80	export function CtxlProvider({
81	  children,
82	  apiMode,
83	  apiKey,
84	  proxyUrl,
85	  model,
86	  esbuildUrl,
87	  esbuildWasmUrl,
88	  dbName,
89	  seeds,
90	  callbacks,
91	  fallback,
92	  exposeGlobals,
93	}: CtxlProviderProps) {
94	  const [ctx, setCtx] = useState<RuntimeContextValue | null>(null);
95	  const [error, setError] = useState<string | null>(null);
96	  const bootedRef = useRef(false);
97	
98	  // Stable reference to callbacks
99	  const cbRef = useRef(callbacks);
100	  cbRef.current = callbacks;
101	
102	  useEffect(() => {
103	    if (bootedRef.current) return;
104	    bootedRef.current = true;
105	
106	    initSystem({
107	      apiMode,
108	      apiKey,
109	      proxyUrl,
110	      model,
111	      esbuildUrl,
112	      esbuildWasmUrl,
113	      dbName,
114	      seeds,
115	      callbacks: cbRef.current,
116	      exposeGlobals,
117	    })
118	      .then(setCtx)
119	      .catch((err: any) => {
120	        console.error("[CtxlProvider] Boot failed:", err);
121	        setError(err.message || String(err));
122	      });
123	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
124	
125	  if (error) {
126	    return React.createElement("div", {
127	      style: { padding: 20, color: "#c00", fontFamily: "monospace" },
128	    }, "ctxl boot error: " + error);
129	  }
130	
131	  if (!ctx) {
132	    return (fallback ?? null) as React.ReactElement | null;
133	  }
134	
135	  return React.createElement(HostRuntimeContext.Provider, { value: ctx }, children);
136	}
