1	/**
2	 * editor.ts — CodeMirror 6 wrapper for the dev-harness VFS editor.
3	 *
4	 * Provides a thin abstraction so boot.ts can get/set content and
5	 * listen for changes without touching CM internals directly.
6	 */
7	
8	import { basicSetup, EditorView } from "codemirror";
9	import { javascript } from "@codemirror/lang-javascript";
10	import { oneDark } from "@codemirror/theme-one-dark";
11	import { EditorState, Compartment } from "@codemirror/state";
12	import { keymap } from "@codemirror/view";
13	
14	export interface EditorInstance {
15	  /** Get the full document text. */
16	  getValue(): string;
17	  /** Replace the entire document. */
18	  setValue(text: string): void;
19	  /** Focus the editor. */
20	  focus(): void;
21	  /** The underlying CM6 EditorView (escape hatch). */
22	  view: EditorView;
23	}
24	
25	/**
26	 * Mount a CodeMirror 6 editor inside `parent`.
27	 *
28	 * @param parent   DOM element to mount into (replaces its children)
29	 * @param opts.onChange  Called on every document change
30	 * @param opts.onSave   Called when Ctrl/Cmd+S is pressed inside the editor
31	 */
32	export function createEditor(
33	  parent: HTMLElement,
34	  opts: {
35	    onChange?: () => void;
36	    onSave?: () => void;
37	  } = {},
38	): EditorInstance {
39	  const language = new Compartment();
40	
41	  const saveKeymap = keymap.of([
42	    {
43	      key: "Mod-s",
44	      run() {
45	        opts.onSave?.();
46	        return true;
47	      },
48	    },
49	  ]);
50	
51	  const changeListener = EditorView.updateListener.of((update) => {
52	    if (update.docChanged) opts.onChange?.();
53	  });
54	
55	  const theme = EditorView.theme({
56	    "&": { height: "100%" },
57	    ".cm-scroller": { overflow: "auto" },
58	    ".cm-content": { fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', monospace", fontSize: "12px", lineHeight: "1.4" },
59	    ".cm-gutters": { fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace", fontSize: "12px" },
60	  });
61	
62	  const view = new EditorView({
63	    state: EditorState.create({
64	      doc: "",
65	      extensions: [
66	        basicSetup,
67	        language.of(javascript({ jsx: true, typescript: true })),
68	        oneDark,
69	        theme,
70	        saveKeymap,
71	        changeListener,
72	        EditorView.lineWrapping,
73	      ],
74	    }),
75	    parent,
76	  });
77	
78	  return {
79	    getValue() {
80	      return view.state.doc.toString();
81	    },
82	    setValue(text: string) {
83	      view.dispatch({
84	        changes: { from: 0, to: view.state.doc.length, insert: text },
85	      });
86	    },
87	    focus() {
88	      view.focus();
89	    },
90	    view,
91	  };
92	}
