1	/**
2	 * Runtime factory.
3	 *
4	 * Creates the core runtime object that manages the VFS build pipeline,
5	 * LLM transport, component authoring, and React Refresh integration.
6	 */
7	import { createVFSPlugin } from "./vfs-plugin";
8	import { buildAuthoringPrompt } from "./prompts";
9	import { callLLM as llmTransport } from "./llm";
10	import type {
11	  Runtime,
12	  RuntimeOptions,
13	  FilePatch,
14	  ToolDef,
15	} from "./types";
16	
17	export function createRuntime({
18	  esbuild,
19	  idb,
20	  files,
21	  config,
22	  callbacks = {},
23	}: RuntimeOptions): Runtime {
24	  let currentBlobUrl: string | null = null;
25	  let buildCounter = 0;
26	
27	  const {
28	    onStatus = () => {},
29	    onMode = () => {},
30	    onFileChange = () => {},
31	    onBuildStart = () => {},
32	    onBuildEnd = () => {},
33	    onError = () => {},
34	  } = callbacks;
35	
36	  const runtime: Runtime = {
37	    files,
38	    disposers: [],
39	    config,
40	    RefreshRuntime: null,
41	
42	    // ---- Config persistence ----
43	
44	    saveConfig() {
45	      localStorage.setItem("__RUNTIME_CONFIG__", JSON.stringify(this.config));
46	    },
47	
48	    // ---- Unified LLM transport ----
49	
50	    async callLLM(system: string, messages: Array<{ role: string; content: any }>, extras?: Record<string, any>) {
51	      return llmTransport(this.config, system, messages, extras);
52	    },
53	
54	    // ---- Authoring prompt builder (bridged to VFS AbstractComponent) ----
55	
56	    buildAuthoringPrompt(componentId: string, inputs: Record<string, any>, tools: ToolDef[], handlers?: Record<string, string>, guidelines?: string, existingSource?: string): string {
57	      return buildAuthoringPrompt(componentId, inputs, tools, handlers, guidelines, existingSource);
58	    },
59	
60	    // ---- Component registry regeneration ----
61	
62	    regenerateRegistry() {
63	      const acFiles = [...files.keys()].filter(
64	        p => p.startsWith("/src/ac/") && p.endsWith(".tsx") && !p.endsWith("_registry.ts")
65	      );
66	
67	      const imports: string[] = [];
68	      const entries: string[] = [];
69	
70	      acFiles.forEach((path, i) => {
71	        const id = path.replace("/src/ac/", "").replace(".tsx", "");
72	        imports.push(`import C${i} from "./${id}";`);
73	        entries.push(`  "${id}": C${i}`);
74	      });
75	
76	      const source = acFiles.length === 0
77	        ? `// Auto-generated component registry.\n(window as any).__COMPONENTS__ ??= {};\n`
78	        : `// Auto-generated component registry.\n${imports.join("\n")}\n\n(window as any).__COMPONENTS__ = {\n${entries.join(",\n")}\n};\n`;
79	
80	      files.set("/src/ac/_registry.ts", source);
81	      idb.put("/src/ac/_registry.ts", source).catch(e => console.warn("[registry] persist failed", e));
82	      onFileChange("/src/ac/_registry.ts", source);
83	    },
84	
85	    // ---- IDB access (bridged to VFS AbstractComponent for persistence) ----
86	
87	    get idb() { return idb; },
88	
89	    // ---- Apply file patches and rebuild ----
90	
91	    async applyPatch(patches: FilePatch[]) {
92	      for (const p of patches) {
93	        files.set(p.path, p.text);
94	        await idb.put(p.path, p.text);
95	        onFileChange(p.path, p.text);
96	      }
97	      try {
98	        await this.buildAndRun("applyPatch");
99	      } catch (err: any) {
100	        onMode("error", "err");
101	        onStatus(String(err?.stack || err));
102	        onError(err);
103	        throw err;
104	      }
105	    },
106	
107	    // ---- Dispose protocol ----
108	
109	    runDisposers() {
110	      while (this.disposers.length) {
111	        const fn = this.disposers.pop()!;
112	        try { fn(); } catch (e) { console.warn("[dispose]", e); }
113	      }
114	    },
115	
116	    // ---- Build pipeline ----
117	
118	    async buildBundle(entry = "/src/main.tsx") {
119	      const t0 = performance.now();
120	      const result = await esbuild.build({
121	        entryPoints: [entry],
122	        bundle: true,
123	        format: "esm",
124	        platform: "browser",
125	        sourcemap: "inline",
126	        write: false,
127	        jsx: "automatic",
128	        plugins: [createVFSPlugin(files, { RefreshRuntime: this.RefreshRuntime })],
129	      });
130	      const out = result.outputFiles?.[0];
131	      if (!out?.text) throw new Error("esbuild produced no output");
132	      return { code: out.text, ms: Math.round(performance.now() - t0) };
133	    },
134	
135	    async importBundle(code: string) {
136	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
137	      const blob = new Blob([code], { type: "text/javascript" });
138	      currentBlobUrl = URL.createObjectURL(blob);
139	      return import(/* @vite-ignore */ currentBlobUrl);
140	    },
141	
142	    async buildAndRun(reason = "manual") {
143	      onMode("building", "warn");
144	      onStatus(`Building (${reason})...`);
145	      onBuildStart();
146	
147	      const { code, ms } = await this.buildBundle();
148	      buildCounter++;
149	      this.runDisposers();
150	      onMode("importing", "warn");
151	      onStatus(`Build #${buildCounter} OK in ${ms}ms. Importing...`);
152	      await this.importBundle(code);
153	
154	      if (this.RefreshRuntime) {
155	        setTimeout(() => this.RefreshRuntime.performReactRefresh(), 30);
156	      }
157	
158	      onMode("running", "");
159	      onStatus(`Build #${buildCounter} running. (${ms}ms)`);
160	      onBuildEnd(buildCounter, ms);
161	    },
162	
163	    // ---- Init React Refresh ----
164	
165	    async initRefresh() {
166	      try {
167	        const RefreshRuntime = await import(/* @vite-ignore */ "react-refresh/runtime");
168	        RefreshRuntime.injectIntoGlobalHook(window);
169	        window.$RefreshReg$ = () => {};
170	        window.$RefreshSig$ = () => (type: any) => type;
171	        this.RefreshRuntime = RefreshRuntime;
172	        return true;
173	      } catch (err) {
174	        console.error("[ctxl] React Refresh failed:", err);
175	        return false;
176	      }
177	    },
178	
179	    // ---- Init esbuild ----
180	
181	    async initEsbuild(wasmURL = "https://unpkg.com/esbuild-wasm@0.24.2/esbuild.wasm") {
182	      onMode("init", "warn");
183	      await esbuild.initialize({ wasmURL, worker: true });
184	      onMode("ready", "");
185	    },
186	
187	    // ---- Reset to seed state ----
188	
189	    async reset() {
190	      await idb.clear();
191	      location.reload();
192	    },
193	  };
194	
195	  return runtime;
196	}
