1	/**
2	 * LLM transport — single fetch function supporting Anthropic direct and proxy modes.
3	 *
4	 * Accepts arbitrary extra body fields (tools, tool_choice, etc.)
5	 * so callers don't need to duplicate the fetch plumbing.
6	 *
7	 * Every call is logged to window.__LOG__ for the dev drawer's Log tab.
8	 */
9	import type { RuntimeConfig } from "./types";
10	
11	export interface LLMResponse {
12	  error: string | null;
13	  data: any;
14	}
15	
16	// ---- Transcript log ----
17	
18	export interface LogEntry {
19	  id: string;
20	  timestamp: number;
21	  /** Who initiated: "author:{id}" | "reasoning:{id}" | "unknown" */
22	  source: string;
23	  system: string;
24	  messages: Array<{ role: string; content: any }>;
25	  tools?: any[];
26	  toolChoice?: any;
27	  model: string;
28	  response?: any;
29	  error?: string;
30	  durationMs?: number;
31	}
32	
33	function pushLog(entry: LogEntry) {
34	  const w = window as any;
35	  if (!w.__LOG__) w.__LOG__ = [];
36	  w.__LOG__.push(entry);
37	  // Cap at 100 entries
38	  if (w.__LOG__.length > 100) w.__LOG__.splice(0, w.__LOG__.length - 100);
39	}
40	
41	export async function callLLM(
42	  config: RuntimeConfig,
43	  system: string,
44	  messages: Array<{ role: string; content: any }>,
45	  extras?: Record<string, any>,
46	): Promise<LLMResponse> {
47	  const { apiMode, apiKey, proxyUrl, model } = config;
48	
49	  const logEntry: LogEntry = {
50	    id: Math.random().toString(36).slice(2, 10),
51	    timestamp: Date.now(),
52	    source: (extras as any)?._source || "unknown",
53	    system,
54	    messages,
55	    tools: extras?.tools,
56	    toolChoice: extras?.tool_choice,
57	    model: model || "claude-sonnet-4-5-20250929",
58	  };
59	
60	  if (apiMode === "none") {
61	    logEntry.error = "No API configured";
62	    pushLog(logEntry);
63	    return { error: "No API configured. Set API mode in settings.", data: null };
64	  }
65	
66	  // Strip internal _source from extras before sending
67	  const { _source, ...cleanExtras } = (extras || {}) as any;
68	
69	  const body: Record<string, any> = {
70	    system,
71	    messages,
72	    model: model || "claude-sonnet-4-5-20250929",
73	    max_tokens: 8192,
74	    ...cleanExtras,
75	  };
76	
77	  const t0 = performance.now();
78	
79	  try {
80	    let response: Response;
81	
82	    if (apiMode === "anthropic") {
83	      response = await fetch("https://api.anthropic.com/v1/messages", {
84	        method: "POST",
85	        headers: {
86	          "Content-Type": "application/json",
87	          "x-api-key": apiKey,
88	          "anthropic-version": "2023-06-01",
89	          "anthropic-dangerous-direct-browser-access": "true",
90	        },
91	        body: JSON.stringify(body),
92	      });
93	    } else if (apiMode === "proxy") {
94	      response = await fetch(proxyUrl, {
95	        method: "POST",
96	        headers: { "Content-Type": "application/json" },
97	        body: JSON.stringify(body),
98	      });
99	    } else {
100	      logEntry.error = "Unsupported API mode: " + apiMode;
101	      logEntry.durationMs = Math.round(performance.now() - t0);
102	      pushLog(logEntry);
103	      return { error: "Unsupported API mode: " + apiMode, data: null };
104	    }
105	
106	    logEntry.durationMs = Math.round(performance.now() - t0);
107	
108	    if (!response.ok) {
109	      const errText = await response.text();
110	      logEntry.error = `API error ${response.status}: ${errText}`;
111	      pushLog(logEntry);
112	      return { error: `API error ${response.status}: ${errText}`, data: null };
113	    }
114	
115	    const data = await response.json();
116	    logEntry.response = data;
117	    pushLog(logEntry);
118	    return { error: null, data };
119	  } catch (err: any) {
120	    logEntry.error = err.message || String(err);
121	    logEntry.durationMs = Math.round(performance.now() - t0);
122	    pushLog(logEntry);
123	    return { error: err.message || String(err), data: null };
124	  }
125	}
126	
127	/** Extract text content from an Anthropic Messages API response. */
128	export function extractText(data: any): string {
129	  if (!data?.content) return "";
130	  const textBlock = data.content.find((b: any) => b.type === "text");
131	  return textBlock?.text || "";
132	}
133	
134	/** Extract a tool_use block by name from an Anthropic Messages API response. */
135	export function extractToolUse(data: any, toolName: string): any | null {
136	  if (!data?.content) return null;
137	  const block = data.content.find(
138	    (b: any) => b.type === "tool_use" && b.name === toolName,
139	  );
140	  return block?.input ?? null;
141	}
