1	/**
2	 * esbuild VFS plugin.
3	 *
4	 * Resolves imports against the in-memory VFS map and injects
5	 * React Refresh registration for TSX/JSX files.
6	 */
7	import { injectReactRefresh } from "./refresh";
8	import type { EsbuildPlugin } from "./types";
9	
10	interface VFSPluginOptions {
11	  RefreshRuntime?: any;
12	}
13	
14	export function createVFSPlugin(
15	  filesMap: Map<string, string>,
16	  options: VFSPluginOptions = {},
17	): EsbuildPlugin {
18	  const { RefreshRuntime } = options;
19	  return {
20	    name: "vfs",
21	    setup(build) {
22	      build.onResolve({ filter: /.*/ }, (args: any) => {
23	        if (args.kind === "entry-point") {
24	          return { path: args.path, namespace: "vfs" };
25	        }
26	        // Bare imports (react, styled-components, etc.) → external
27	        if (!args.path.startsWith(".") && !args.path.startsWith("/")) {
28	          return { path: args.path, external: true };
29	        }
30	        const baseDir: string = args.resolveDir || "/";
31	        const resolved = new URL(args.path, "file://" + baseDir + "/").pathname;
32	        const candidates = [
33	          resolved,
34	          resolved + ".ts", resolved + ".tsx",
35	          resolved + ".js", resolved + ".jsx",
36	          resolved + "/index.ts", resolved + "/index.tsx",
37	          resolved + "/index.js", resolved + "/index.jsx",
38	        ];
39	        const hit = candidates.find((p) => filesMap.has(p));
40	        if (!hit) {
41	          throw new Error(`Module not found: ${args.path} (from ${args.importer || "?"})`);
42	        }
43	        return { path: hit, namespace: "vfs" };
44	      });
45	
46	      build.onLoad({ filter: /.*/, namespace: "vfs" }, (args: any) => {
47	        let contents: string | undefined = filesMap.get(args.path);
48	        if (contents == null) {
49	          throw new Error(`Missing file: ${args.path}`);
50	        }
51	        const loader =
52	          args.path.endsWith(".tsx") ? "tsx" :
53	          args.path.endsWith(".ts") ? "ts" :
54	          args.path.endsWith(".jsx") ? "jsx" : "js";
55	
56	        if ((loader === "tsx" || loader === "jsx") && RefreshRuntime) {
57	          contents = injectReactRefresh(contents, args.path);
58	        }
59	        const resolveDir = args.path.slice(0, args.path.lastIndexOf("/")) || "/";
60	        return { contents, loader, resolveDir };
61	      });
62	    },
63	  };
64	}
