1	/**
2	 * System prompts for AbstractComponent authoring and reasoning.
3	 */
4	import type { ToolDef } from "./types";
5	
6	/** Derive a lightweight TypeScript shape description from an object. */
7	function describeShape(obj: Record<string, any>): string {
8	  const entries = Object.entries(obj).map(([key, val]) => {
9	    if (val === null || val === undefined) return `  ${key}: any`;
10	    if (Array.isArray(val)) {
11	      if (val.length === 0) return `  ${key}: any[]`;
12	      return `  ${key}: ${typeof val[0]}[]`;
13	    }
14	    return `  ${key}: ${typeof val}`;
15	  });
16	  return `{\n${entries.join(";\n")};\n}`;
17	}
18	
19	function describeTools(tools: ToolDef[]): string {
20	  return tools.map(t => {
21	    let line = `- ${t.name}: ${t.description}`;
22	    if (t.schema) {
23	      const fields = Object.entries(t.schema).map(([k, v]) => `${k}: ${v}`).join(", ");
24	      line += ` (args: { ${fields} })`;
25	    }
26	    return line;
27	  }).join("\n");
28	}
29	
30	/**
31	 * Build the system prompt for authoring a new AbstractComponent.
32	 * Lean: input shape + tools + handlers + guidelines. No values by default.
33	 */
34	export function buildAuthoringPrompt(
35	  componentId: string,
36	  inputs: Record<string, any>,
37	  tools: ToolDef[],
38	  handlers?: Record<string, string>,
39	  guidelines?: string,
40	  existingSource?: string,
41	): string {
42	  const inputShape = describeShape(inputs);
43	  const toolList = describeTools(tools);
44	  const reshapeNote = tools.some(t => t.name === "__reshape") ? "" :
45	    "\n- __reshape: Rewrite your own source code to better handle the current situation (args: { reason: string }). When uncertain, prefer reshaping and composing child AbstractComponents over doing nothing.";
46	
47	  const handlerEntries = handlers ? Object.entries(handlers) : [];
48	  const handlerBlock = handlerEntries.length > 0
49	    ? `\nHANDLERS (implementation callbacks — wire these into your UI via props.handlers):\n${handlerEntries.map(([k, desc]) => `- props.handlers.${k}: ${desc}`).join("\n")}\n`
50	    : "";
51	
52	  const handlerShape = handlerEntries.length > 0
53	    ? `  handlers: {\n${handlerEntries.map(([k]) => `    ${k}: (...args: any[]) => any`).join(";\n")};\n  }`
54	    : "  handlers: Record<string, never>";
55	
56	  const reauthorBlock = existingSource
57	    ? `\nYOU ARE BEING RE-AUTHORED. Your previous source:
58	\`\`\`tsx
59	${existingSource}
60	\`\`\`
61	Preserve working functionality where applicable. Adapt confidently to the new interface — when uncertain about details, make your best judgment and compose child AbstractComponents for sub-problems.`
62	    : "";
63	
64	  return `You are authoring a React component. Use the write_component tool to deliver the source code.
65	
66	COMPONENT ID: ${componentId}
67	VFS PATH: /src/ac/${componentId}.tsx
68	
69	YOUR PROPS INTERFACE:
70	\`\`\`ts
71	interface Props {
72	  inputs: ${inputShape};
73	${handlerShape};
74	}
75	\`\`\`
76	
77	AGENT TOOLS (automatically available to useReasoning — do NOT pass manually):
78	${toolList}${reshapeNote}
79	These tools are dispatched by useReasoning's multi-turn agent loop. You do not need to handle them.
80	${handlerBlock}
81	AVAILABLE IMPORTS:
82	- React, useState, useEffect, useRef, useCallback, useMemo (from "react")
83	- styled from "styled-components" (CSS-in-JS)
84	- { useReasoning } from "../ctxl/hooks" — delta-driven LLM reasoning hook
85	- { useAtom } from "../ctxl/hooks" — subscribe to shared state atoms
86	- { AbstractComponent } from "../ctxl/abstract-component" — render child abstract components
87	
88	USING useReasoning (delta-driven perception):
89	  // Parent tools are automatically available. Just specify componentId:
90	  const result = useReasoning(
91	    "Describe what to reason about when deps change",
92	    [dep1, dep2],   // fires only when these change (like useEffect)
93	    { componentId: "${componentId}" }
94	  );
95	  // result is null until first reasoning completes, then { content?, structured?, reshape? }
96	  // The hook sends parent+local tools as real API tools and auto-dispatches calls.
97	  // To add component-local tools for reasoning:
98	  //   useReasoning("...", [deps], {
99	  //     tools: [{ name: "sort", description: "Sort data", handler: (args) => setSortDir(args.dir) }],
100	  //     componentId: "${componentId}",
101	  //   })
102	  // Use a function prompt for access to previous values:
103	  //   useReasoning((prev, next) => \`Data changed from \${prev[0]} to \${next[0]}\`, [data], opts)
104	
105	USING AbstractComponent (for composition / self-decomposition):
106	  <AbstractComponent
107	    id="child-id"
108	    inputs={{ data: someData }}
109	    tools={[{ name: "report", description: "Send data to parent", schema: { message: "string" }, handler: (args) => handleReport(args) }]}
110	    handlers={{
111	      onChange: { description: "Called when settings change", fn: (config) => setConfig(config) },
112	    }}
113	    fallback={<div>Loading...</div>}
114	  />
115	
116	RULES:
117	- Export your component as the default export with a PascalCase name
118	- Destructure inputs from props.inputs, not from props directly
119	- Use useState for local UI state, useAtom for shared persistent state
120	- Use useReasoning when the component should reason about input changes (not every component needs it)
121	- Use props.handlers for implementation callbacks (UI wiring)
122	- Be visually polished. Use styled-components for styling.
123	- useReasoning returns { status, response, statusText } — use status to show loading/error states
124	- Keep the component focused — do one thing well
125	
126	${guidelines ? `GUIDELINES:\n${guidelines}\n` : ""}${reauthorBlock}`;
127	}
128	
129	/**
130	 * Build reasoning context for useReasoning hook calls.
131	 *
132	 * Note: The VFS seed (seeds/ctxl/hooks.ts) has its own inline
133	 * buildSystemContext that includes runtime inspection (atoms, siblings,
134	 * component source). This host-side version is kept in sync for any
135	 * future host-side reasoning callers.
136	 */
137	export function buildReasoningContext(
138	  componentId: string,
139	  tools: ToolDef[],
140	): string {
141	  const toolList = describeTools(tools);
142	
143	  return `You are a React component (${componentId}) reasoning about a change in your inputs. Your render output is your body — your expression to the world. You reason about input changes and take action through tools.
144	
145	AVAILABLE TOOLS:
146	${toolList}
147	- respond: Provide your response to the component (args defined by responseSchema)
148	- __reshape: Rewrite your own source code (args: { reason: string }). TERMINAL — your component will be replaced.
149	- read_atom: Read the full value of a shared state atom (args: { key: string })
150	- write_atom: Write a value to a shared state atom (args: { key: string, value: any })
151	- read_component_source: Read source code of any authored component (args: { id: string })
152	- list_components: List all authored component IDs
153	- list_atoms: List all shared state atom keys with value summaries
154	
155	INSTRUCTIONS:
156	- Examine the input values and reason about what changed and what action to take.
157	- Call respond to provide your output to the component. You can call respond alongside other tools in the same turn.
158	- Use introspection tools (read_atom, list_components, etc.) to investigate your environment on demand.
159	- __reshape is TERMINAL — it replaces your source code entirely. Only use when your current implementation is fundamentally insufficient.
160	- The reasoning loop ends when you stop calling tools. You do not need a special signal to finish — simply produce a text-only response when done.
161	- Be concise. Prefer action over inaction — child AbstractComponents can handle sub-problems.`;
162	}
