1	/**
2	 * boot.ts — Dev environment entry point for index.html
3	 *
4	 * Uses the same initSystem() code path as <CtxlProvider> so the dev
5	 * environment dogfoods the identical boot sequence that library consumers get.
6	 * The VFS main.tsx wraps its React tree in <RuntimeContext.Provider>,
7	 * completing the dogfooding loop.
8	 */
9	
10	import { initSystem } from "./init";
11	import { createEditor, type EditorInstance } from "./editor";
12	import type { Runtime, IDB } from "./types";
13	
14	// ============================================================
15	// DOM references
16	// ============================================================
