194	  const mutations: any[] = (window as any).__MUTATIONS__ || [];
195	
196	  let html = "";
197	
198	  // -- Component tree --
199	  html += `<div class="section"><div class="section-title">Components</div>`;
200	  const compIds = Object.keys(components);
201	  if (compIds.length === 0) {
202	    html += `<div class="empty">No authored components yet</div>`;
203	  } else {
204	    for (const id of compIds) {
