211	  html += `</div>`;
212	
213	  // -- Atoms --
214	  html += `<div class="section"><div class="section-title">Atoms</div>`;
215	  if (atoms && typeof atoms.keys === "function") {
216	    const keys: string[] = atoms.keys();
217	    if (keys.length === 0) {
218	      html += `<div class="empty">No atoms</div>`;
219	    } else {
220	      for (const k of keys) {
221	        try {
222	          const v = atoms.get(k)?.get();
223	          const s = JSON.stringify(v);
224	          const display = s && s.length > 120 ? s.slice(0, 120) + "..." : s;
225	          html += `<div class="entry"><span class="entry-key">${k}</span><span class="entry-val">${display}</span></div>`;
226	        } catch {
227	          html += `<div class="entry"><span class="entry-key">${k}</span><span class="entry-val">&lt;unreadable&gt;</span></div>`;
228	        }
229	      }
230	    }
231	  } else {
232	    html += `<div class="empty">No atom registry</div>`;
233	  }
234	  html += `</div>`;
235	
236	  // -- Mutation log --
237	  html += `<div class="section"><div class="section-title">Mutation Log</div>`;
238	  if (mutations.length === 0) {
239	    html += `<div class="empty">No mutations recorded</div>`;
240	  } else {
241	    for (let i = mutations.length - 1; i >= 0; i--) {
242	      const m = mutations[i];
243	      const cls = m.outcome === "rollback" ? "mutation rollback" : "mutation";
244	      const time = new Date(m.timestamp).toLocaleTimeString();
245	      html += `<div class="${cls}"><div class="trigger">[${m.componentId}] ${m.trigger}</div><div class="meta">${m.outcome} at ${time}</div></div>`;
246	    }
247	  }
