255	let lastRenderedLogLen = 0;
256	
257	function escHtml(s: string): string {
258	  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
259	}
260	
261	function summarizeResponse(entry: any): { pills: string; preview: string } {
262	  if (entry.error) {
263	    return { pills: `<span class="log-pill error">error</span>`, preview: escHtml(entry.error).slice(0, 120) };
264	  }
265	  const data = entry.response;
266	  if (!data?.content) return { pills: "", preview: "no content" };
267	
268	  const pills: string[] = [];
269	  let preview = "";
270	  for (const block of data.content) {
271	    if (block.type === "text") {
272	      pills.push(`<span class="log-pill text">text</span>`);
273	      if (!preview) preview = escHtml(block.text || "").slice(0, 80);
274	    } else if (block.type === "tool_use") {
275	      pills.push(`<span class="log-pill tool-use">${escHtml(block.name)}</span>`);
276	      if (!preview && block.input) {
277	        const keys = Object.keys(block.input);
278	        preview = keys.slice(0, 3).join(", ") + (keys.length > 3 ? "..." : "");
279	      }
280	    }
281	  }
282	  return { pills: pills.join(" "), preview };
283	}
284	
285	function buildLogEntryHtml(e: any): string {
286	  const time = new Date(e.timestamp).toLocaleTimeString();
287	  const srcType = e.source.split(":")[0];
288	  const { pills } = summarizeResponse(e);
289	  const dur = e.durationMs != null ? `${e.durationMs}ms` : "";
290	
291	  // Build expandable body content
292	  let body = "";
293	
294	  // For dispatch entries, show compact info
295	  if (srcType === "dispatch") {
296	    const r = e.response || {};
297	    body += `Tool: ${escHtml(r.tool || "?")}\nArgs: ${escHtml(JSON.stringify(r.args, null, 2) || "{}")}\nRoute: ${escHtml(r.route || "?")}\nResult: ${escHtml(JSON.stringify(r.result) || "undefined")}`;
298	  } else {
299	    // Show user messages (truncated)
300	    if (e.messages?.length) {
301	      body += "--- Messages ---\n";
302	      for (const m of e.messages) {
303	        const content = typeof m.content === "string" ? m.content : JSON.stringify(m.content);
304	        body += `[${escHtml(m.role)}] ${escHtml(content.slice(0, 500))}${content.length > 500 ? "..." : ""}\n\n`;
305	      }
306	    }
307	    // Show response content blocks
308	    if (e.response?.content) {
309	      body += "--- Response ---\n";
310	      for (const block of e.response.content) {
311	        if (block.type === "text") {
312	          body += `[text] ${escHtml(block.text || "")}\n\n`;
313	        } else if (block.type === "tool_use") {
314	          body += `[tool_use] ${escHtml(block.name)} (id: ${escHtml(block.id || "")})\n${escHtml(JSON.stringify(block.input, null, 2) || "{}")}\n\n`;
315	        }
316	      }
317	    }
318	    if (e.error) {
319	      body += `--- Error ---\n${escHtml(e.error)}\n`;
320	    }
321	  }
322	
323	  let html = `<div class="log-entry" data-log-id="${escHtml(e.id)}">`;
324	  html += `<div class="log-header" onclick="this.nextElementSibling.classList.toggle('open')">`;
325	  html += `<span class="log-source ${escHtml(srcType)}">${escHtml(e.source)}</span>`;
326	  html += pills;
327	  if (e.error) html += `<span class="log-error">ERR</span>`;
328	  if (dur) html += `<span class="log-duration">${dur}</span>`;
329	  html += `<span class="log-time">${time}</span>`;
330	  html += `</div>`;
331	  html += `<div class="log-body">${body}</div>`;
332	  html += `</div>`;
333	  return html;
334	}
