336	function renderLogPanel() {
337	  const log: any[] = (window as any).__LOG__ || [];
338	
339	  if (log.length === 0) {
340	    if (lastRenderedLogLen !== 0) {
341	      lastRenderedLogLen = 0;
342	      drawerLogEl.innerHTML = `<div class="log-empty">No LLM calls yet. Configure API and interact with a component.</div>`;
343	    }
344	    return;
345	  }
346	
347	  // No new entries — skip re-render to preserve expanded/interaction state
348	  if (log.length === lastRenderedLogLen) return;
349	
350	  // Collect currently expanded entry IDs before DOM update
351	  const expandedIds = new Set<string>();
352	  drawerLogEl.querySelectorAll(".log-body.open").forEach((el) => {
353	    const entry = el.closest(".log-entry") as HTMLElement | null;
354	    if (entry?.dataset.logId) expandedIds.add(entry.dataset.logId);
355	  });
356	
357	  // If the log shrank (capped at 100 via splice) or is the first render,
358	  // do a full rebuild; otherwise only prepend new entries.
359	  if (lastRenderedLogLen === 0 || log.length < lastRenderedLogLen) {
360	    let html = "";
361	    for (let i = log.length - 1; i >= 0; i--) {
362	      html += buildLogEntryHtml(log[i]);
363	    }
364	    drawerLogEl.innerHTML = html;
365	  } else {
366	    // Prepend only new entries at the top (newest first display order)
367	    let newHtml = "";
368	    for (let i = log.length - 1; i >= lastRenderedLogLen; i--) {
369	      newHtml += buildLogEntryHtml(log[i]);
370	    }
371	    drawerLogEl.insertAdjacentHTML("afterbegin", newHtml);
372	  }
373	
374	  lastRenderedLogLen = log.length;
375	
376	  // Restore expanded state for previously open entries
377	  expandedIds.forEach(id => {
378	    const entry = drawerLogEl.querySelector(`.log-entry[data-log-id="${id}"]`);
379	    const body = entry?.querySelector(".log-body");
380	    if (body) body.classList.add("open");
381	  });
382	}
