1	/**
2	 * VFS SEED — imported as raw text, not compiled into the host bundle.
3	 *
4	 * This file is authored as normal TypeScript so it benefits from IDE
5	 * autocompletion and type-checking (via tsconfig.seeds.json), but at build
6	 * time Vite's `?raw` import injects its source text as a string into the
7	 * host bundle.  At runtime esbuild-wasm compiles it inside the browser as
8	 * part of the Virtual File System (VFS).
9	 *
10	 * VFS path:  /src/ctxl/hooks.ts
11	 * Registry:  src/seeds-v2.ts
12	 */
13	
14	import { useState, useEffect, useRef, useCallback, useSyncExternalStore, createContext, useContext } from "react";
15	
16	// ---- Types ----
17	
18	interface ToolDef {
19	  name: string;
20	  description: string;
21	  schema?: Record<string, string>;
22	  handler?: (args: any) => any;
23	}
24	
25	interface UseReasoningOptions<T = { content: string }> {
26	  /** JSON Schema for the respond tool — defines the shape the agent must produce. */
27	  responseSchema?: Record<string, any>;
28	  tools?: ToolDef[];
29	  onToolCall?: (name: string, args: any) => any;
30	  debounceMs?: number;
31	  componentId?: string;
32	  maxTurns?: number;
33	}
34	
35	interface UseReasoningReturn<T = { content: string }> {
36	  status: "idle" | "reasoning" | "done" | "error";
37	  response: T | null;
38	  error: string | null;
39	  turn: number;
40	  maxTurns: number;
41	  statusText: string | null;
42	}
43	
44	// ---- Runtime Context ----
45	// Provides runtime + atoms via React Context so that library consumers
46	// can wrap their existing React tree in <RuntimeProvider> and have
47	// AbstractComponent, useAtom, and useReasoning work without globals.
48	
49	interface RuntimeContextValue {
50	  runtime: any;
51	  atoms: any;
52	}
53	
54	export const RuntimeContext = createContext<RuntimeContextValue | null>(null);
55	
56	/**
57	 * Read runtime + atoms from React Context, falling back to window globals.
58	 * This allows VFS code to work both inside a <RuntimeProvider> tree
59	 * and in the legacy globals-only boot path.
60	 */
61	export function useRuntimeContext(): RuntimeContextValue {
62	  const ctx = useContext(RuntimeContext);
63	  return ctx || {
64	    runtime: (window as any).__RUNTIME__,
65	    atoms: (window as any).__ATOMS__,
66	  };
67	}
68	
69	// ---- Tool Context ----
70	// Parent-provided tools are injected via React Context by AbstractComponent.
71	// useReasoning reads from this context automatically — child components
72	// never need to thread tools/onToolCall through props.
73	
74	interface ToolContextValue {
75	  tools: ToolDef[];
76	  dispatch: (name: string, args: any) => any;
77	  reshape: (reason: string) => void;
78	  componentId: string;
79	}
80	
81	export const ToolContext = createContext<ToolContextValue | null>(null);
82	
83	// ---- Build system context from tools ----
84	
85	function buildSystemContext(
86	  tools: ToolDef[],
87	  componentId?: string,
88	  runtimeCtx?: RuntimeContextValue | null,
89	  responseSchema?: Record<string, any>,
90	): string {
91	  const id = componentId || "anonymous";
92	
93	  // Tool descriptions (text context for the LLM alongside real API tools)
94	  const toolLines = tools.map(function(t) {
95	    let line = "- " + t.name + ": " + t.description;
96	    if (t.schema) {
97	      const fields = Object.entries(t.schema).map(function(e) { return e[0] + ": " + e[1]; }).join(", ");
98	      line += " (args: { " + fields + " })";
99	    }
100	    return line;
101	  });
102	
103	  // Built-in tools always available
104	  if (responseSchema && responseSchema.properties) {
105	    const fields = Object.keys(responseSchema.properties).join(", ");
106	    toolLines.push("- respond: Provide your response to the component (fields: " + fields + ")");
107	  } else {
108	    toolLines.push("- respond: Provide your response to the component (args: { content: string })");
109	  }
110	  toolLines.push("- __reshape: Rewrite your own source code (args: { reason: string }). TERMINAL — your component will be replaced.");
111	  toolLines.push("- read_atom: Read the full value of a shared state atom (args: { key: string })");
112	  toolLines.push("- write_atom: Write a value to a shared state atom (args: { key: string, value: any })");
113	  toolLines.push("- read_component_source: Read source code of any authored component (args: { id: string })");
114	  toolLines.push("- list_components: List all authored component IDs");
115	  toolLines.push("- list_atoms: List all shared state atom keys with value summaries");
116	
117	  // Component source for self-awareness
118	  let sourceBlock = "";
119	  try {
120	    const runtime = runtimeCtx?.runtime;
121	    if (runtime?.files) {
122	      const source = runtime.files.get("/src/ac/" + id + ".tsx");
123	      if (source && source.length < 4000) {
124	        sourceBlock = "\n\nYOUR CURRENT SOURCE:\n" + source;
125	      } else if (source) {
126	        sourceBlock = "\n\nYOUR CURRENT SOURCE: (" + source.length + " chars, truncated)\n" + source.slice(0, 3000) + "\n...(truncated)";
127	      }
128	    }
129	  } catch {}
130	
131	  // Inspection context: atom state + sibling components (summaries for awareness)
132	  let inspectionBlock = "";
133	  try {
134	    const atoms = runtimeCtx?.atoms || (window as any).__ATOMS__;
135	    if (atoms && typeof atoms.keys === "function") {
136	      const atomKeys = atoms.keys();
137	      if (atomKeys.length > 0) {
138	        const atomSummary = atomKeys.map(function(k: string) {
139	          try {
140	            const v = atoms.get(k)?.get();
141	            const s = JSON.stringify(v);
142	            return "  " + k + ": " + (s && s.length > 80 ? s.slice(0, 80) + "..." : s);
143	          } catch { return "  " + k + ": <unreadable>"; }
144	        }).join("\n");
145	        inspectionBlock += "\n\nSHARED STATE (atoms):\n" + atomSummary;
146	      }
147	    }
148	    const components = (window as any).__COMPONENTS__;
149	    if (components) {
150	      const siblings = Object.keys(components).filter(function(k) { return k !== id; });
151	      if (siblings.length > 0) {
152	        inspectionBlock += "\n\nSIBLING COMPONENTS: " + siblings.join(", ");
153	      }
154	    }
155	  } catch {}
156	
157	  return "You are a React component (" + id + ") reasoning about a change in your inputs. Your render output is your body — your expression to the world. You reason about input changes and take action through tools." +
158	    sourceBlock +
159	    "\n\nAVAILABLE TOOLS:\n" + toolLines.join("\n") +
160	    inspectionBlock +
161	    "\n\nINSTRUCTIONS:" +
162	    "\n- Examine the input values and reason about what changed and what action to take." +
163	    "\n- Call respond to provide your output to the component. You can call respond alongside other tools in the same turn." +
164	    "\n- Use introspection tools (read_atom, list_components, etc.) to investigate your environment on demand." +
165	    "\n- __reshape is TERMINAL — it replaces your source code entirely. Only use when your current implementation is fundamentally insufficient." +
166	    "\n- The reasoning loop ends when you stop calling tools. You do not need a special signal to finish — simply produce a text-only response when done." +
167	    "\n- Be concise. Prefer action over inaction — child AbstractComponents can handle sub-problems.";
168	}
