172	/**
173	 * Delta-driven LLM reasoning hook.
174	 *
175	 * Fires when deps change (like useEffect). Sends the prompt + delta to the LLM
176	 * with scoped tools. Returns a rich status object that the component can use to
177	 * render loading states, errors, and typed responses.
178	 *
179	 * Usage:
180	 *   const { status, response, statusText } = useReasoning<MyData>(
181	 *     "Analyze this data", [data], {
182	 *       responseSchema: { type: "object", properties: { ... }, required: [...] },
183	 *       tools,
184	 *     }
185	 *   );
186	 *
187	 *   if (status === "reasoning") return <Spinner label={statusText} />;
188	 *   if (response) return <MyUI data={response} />;
189	 */
190	export function useReasoning<T = { content: string }>(
191	  prompt: string | ((prev: any[], next: any[]) => string),
192	  deps: any[],
193	  options: UseReasoningOptions<T> = {},
194	): UseReasoningReturn<T> {
195	  const resolvedMaxTurns = options.maxTurns ?? 3;
196	  const [state, setState] = useState<UseReasoningReturn<T>>({
197	    status: "idle",
198	    response: null,
199	    error: null,
200	    turn: 0,
201	    maxTurns: resolvedMaxTurns,
202	    statusText: null,
203	  });
204	  const prevDepsRef = useRef<any[] | null>(null);
205	  const fireCountRef = useRef(0);
206	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
207	  const mountedRef = useRef(true);
208	
209	  // Runtime from context (falls back to globals)
210	  const { runtime: ctxRuntime } = useRuntimeContext();
211	
212	  // Parent tool context (provided by AbstractComponent)
213	  const parentCtx = useContext(ToolContext);
214	  const parentCtxRef = useRef(parentCtx);
215	  parentCtxRef.current = parentCtx;
216	
217	  // Stable reference to options
218	  const optionsRef = useRef(options);
219	  optionsRef.current = options;
220	
221	  // Helper: update state if still mounted
222	  const update = useCallback((patch: Partial<UseReasoningReturn<T>>) => {
223	    if (mountedRef.current) {
224	      setState(function(prev) { return { ...prev, ...patch } as UseReasoningReturn<T>; });
225	    }
226	  }, []);
227	
228	  useEffect(() => {
229	    mountedRef.current = true;
230	    return () => { mountedRef.current = false; };
231	  }, []);
232	
233	  useEffect(() => {
234	    const prevDeps = prevDepsRef.current;
235	    prevDepsRef.current = deps;
236	
237	    // Max fire count per mount to prevent runaway
238	    if (fireCountRef.current >= 10) {
239	      console.warn("[useReasoning] Max fire count reached, stopping");
240	      return;
241	    }
242	
243	    const doReason = async () => {
244	      const runtime = ctxRuntime;
245	      if (!runtime) return;
246	
247	      const resolvedPrompt = typeof prompt === "function"
248	        ? prompt(prevDeps || [], deps)
249	        : prompt;
250	
251	      if (!resolvedPrompt) return;
252	
253	      fireCountRef.current++;
254	
255	      const { tools: localTools = [], onToolCall: localOnToolCall, componentId: optComponentId, maxTurns = 3, responseSchema } = optionsRef.current;
256	
257	      update({ status: "reasoning", response: null, error: null, turn: 0, maxTurns, statusText: "Thinking..." });
258	
259	      try {
260	        const config = runtime.config;
261	        if (config.apiMode === "none") {
262	          update({ status: "error", error: "No API configured.", statusText: null });
263	          return;
264	        }
265	
266	        // Merge parent tools (from context) with component-local tools
267	        const ctx = parentCtxRef.current;
268	        const parentTools = ctx?.tools ?? [];
269	        const allTools = [...parentTools, ...localTools];
270	        const componentId = optComponentId || ctx?.componentId;
271	
272	        // Track the latest response from the respond tool (last call wins)
273	        let latestResponse: T | null = null;
274	
275	        // Unified dispatch: routes to builtin → parent → local → onToolCall
276	        const dispatchTool = (name: string, args: any): any => {
277	          const logDispatch = (route: string, result: any) => {
278	            const w = window as any;
279	            if (!w.__LOG__) w.__LOG__ = [];
280	            w.__LOG__.push({
281	              id: Math.random().toString(36).slice(2, 10),
282	              timestamp: Date.now(),
283	              source: "dispatch:" + (componentId || "anonymous"),
284	              system: "", messages: [], model: "",
285	              response: { tool: name, args, route, result },
286	            });
287	          };
288	          // __reshape always goes to context — TERMINAL
289	          if (name === "__reshape") {
290	            if (ctx?.reshape) { ctx.reshape(args?.reason || "self-requested"); logDispatch("reshape", "triggered"); return "reshape triggered"; }
291	            logDispatch("reshape", "no context");
292	            return undefined;
293	          }
294	          // Built-in introspection tools — always available
295	          if (name === "read_atom") {
296	            const atoms = (window as any).__ATOMS__;
297	            if (!atoms) { logDispatch("builtin", "No atom registry"); return "No atom registry available"; }
298	            const atom = atoms.get(args?.key);
299	            if (!atom) { logDispatch("builtin", "not found"); return "Atom not found: " + args?.key; }
300	            try { const v = JSON.stringify(atom.get(), null, 2); logDispatch("builtin", v); return v; }
301	            catch { logDispatch("builtin", "<unreadable>"); return "<unreadable>"; }
302	          }
303	          if (name === "write_atom") {
304	            const atoms = (window as any).__ATOMS__;
305	            if (!atoms) { logDispatch("builtin", "No atom registry"); return "No atom registry available"; }
306	            const atom = atoms.create(args?.key, undefined);
307	            try {
308	              atom.set(args?.value);
309	              logDispatch("builtin", "written");
310	              return "Atom '" + args?.key + "' updated";
311	            } catch (e: any) { logDispatch("builtin", "error: " + e.message); return "Error writing atom: " + e.message; }
312	          }
313	          if (name === "read_component_source") {
314	            const cid = args?.id || "";
315	            const source = runtime.files.get("/src/ac/" + cid + ".tsx");
316	            const result = source || "No source found for component: " + cid;
317	            logDispatch("builtin", source ? source.length + " chars" : "not found");
318	            return result;
319	          }
320	          if (name === "list_components") {
321	            const comps = (window as any).__COMPONENTS__ || {};
322	            const ids = Object.keys(comps);
323	            const result = ids.length > 0 ? ids.join(", ") : "No authored components";
324	            logDispatch("builtin", result);
325	            return result;
326	          }
327	          if (name === "list_atoms") {
328	            const atoms = (window as any).__ATOMS__;
329	            if (!atoms || typeof atoms.keys !== "function") { logDispatch("builtin", "no registry"); return "No atom registry available"; }
330	            const keys: string[] = atoms.keys();
331	            if (keys.length === 0) { logDispatch("builtin", "empty"); return "No atoms"; }
332	            const result = keys.map(function(k: string) {
333	              try {
334	                const v = atoms.get(k)?.get();
335	                const s = JSON.stringify(v);
336	                return k + ": " + (s && s.length > 120 ? s.slice(0, 120) + "..." : s);
337	              } catch { return k + ": <unreadable>"; }
338	            }).join("\n");
339	            logDispatch("builtin", keys.length + " atoms");
340	            return result;
341	          }
342	          // Parent tool — dispatch via context
343	          if (ctx && parentTools.some((t: any) => t.name === name)) {
344	            const result = ctx.dispatch(name, args);
345	            logDispatch("parent", result);
346	            return result;
347	          }
348	          // Local tool with inline handler
349	          const localTool = localTools.find((t: any) => t.name === name);
350	          if (localTool && typeof localTool.handler === "function") {
351	            const result = localTool.handler(args);
352	            logDispatch("local", result);
353	            return result;
354	          }
355	          // Fallback to onToolCall
356	          if (localOnToolCall) {
357	            const result = localOnToolCall(name, args);
358	            logDispatch("onToolCall", result);
359	            return result;
360	          }
361	          logDispatch("unhandled", undefined);
362	          console.warn("[useReasoning] No handler for tool: " + name);
363	          return undefined;
364	        };
365	
366	        // respond tool — non-terminal. Schema from responseSchema option,
367	        // or default to { content: string }.
368	        const respondTool = {
369	          name: "respond",
370	          description: "Provide your response to the component. Call this when you have determined what the component needs. You can call other tools in the same turn.",
371	          input_schema: responseSchema || {
372	            type: "object" as const,
373	            properties: {
374	              content: { type: "string", description: "Your response text" },
375	            },
376	            required: ["content"],
377	          },
378	        };
379	
380	        // __reshape — the only terminal tool (component will be replaced)
381	        const reshapeTool = {
382	          name: "__reshape",
383	          description: "Rewrite your own source code to better handle the current situation. TERMINAL: your component will be replaced. Prefer composing child AbstractComponents for sub-problems.",
384	          input_schema: {
385	            type: "object",
386	            properties: {
387	              reason: { type: "string", description: "Why you need to be rewritten and what the new version should handle" },
388	            },
389	            required: ["reason"],
390	          },
391	        };
392	
393	        // Built-in introspection tools (v2 §5.2 inspection tool pattern)
394	        const introspectionTools = [
395	          {
396	            name: "read_atom",
397	            description: "Read the full current value of a shared state atom by key",
398	            input_schema: {
399	              type: "object",
400	              properties: { key: { type: "string", description: "The atom key to read" } },
401	              required: ["key"],
402	            },
403	          },
404	          {
405	            name: "write_atom",
406	            description: "Write a value to a shared state atom. Creates the atom if it doesn't exist.",
407	            input_schema: {
408	              type: "object",
409	              properties: {
410	                key: { type: "string", description: "The atom key to write" },
411	                value: { description: "The value to set (any JSON-serializable value)" },
412	              },
413	              required: ["key", "value"],
414	            },
415	          },
416	          {
417	            name: "read_component_source",
418	            description: "Read the source code of any authored component by its ID",
419	            input_schema: {
420	              type: "object",
421	              properties: { id: { type: "string", description: "The component ID (maps to /src/ac/{id}.tsx)" } },
422	              required: ["id"],
423	            },
424	          },
425	          {
426	            name: "list_components",
427	            description: "List all authored component IDs currently in the system",
428	            input_schema: { type: "object", properties: {} },
429	          },
430	          {
431	            name: "list_atoms",
432	            description: "List all shared state atom keys with value summaries",
433	            input_schema: { type: "object", properties: {} },
434	          },
435	        ];
436	
437	        // Convert ToolDef[] → Anthropic API tool format
438	        const toAPITool = (t: ToolDef) => {
439	          const properties: Record<string, any> = {};
440	          if (t.schema) {
441	            for (const [key, type] of Object.entries(t.schema)) {
442	              properties[key] = { type };
443	            }
444	          }
445	          return {
446	            name: t.name,
447	            description: t.description,
448	            input_schema: { type: "object" as const, properties },
449	          };
450	        };
451	
452	        // All API tools: respond (non-terminal), __reshape (terminal),
453	        // introspection (non-terminal), domain (non-terminal)
454	        const apiTools = [respondTool, reshapeTool, ...introspectionTools, ...allTools.map(toAPITool)];
455	
456	        // Build system context
457	        const runtimeCtx = { runtime: ctxRuntime, atoms: (window as any).__ATOMS__ };
458	        const system = buildSystemContext(allTools, componentId, runtimeCtx, responseSchema);
459	
460	        // Build user message with dependency values
461	        let userMessage = resolvedPrompt;
462	        if (deps.length > 0) {
463	          const depsDesc = deps.map(function(d: any, i: number) {
464	            try {
465	              const s = JSON.stringify(d, null, 2);
466	              const truncated = s && s.length > 2000 ? s.slice(0, 2000) + "...(truncated)" : s;
467	              return "  [" + i + "]: " + truncated;
468	            } catch { return "  [" + i + "]: " + String(d); }
469	          }).join("\n");
470	          userMessage += "\n\nCURRENT INPUT VALUES:\n" + depsDesc;
471	        }
472	        if (prevDeps) {
473	          const prevDesc = prevDeps.map(function(d: any, i: number) {
474	            try {
475	              const s = JSON.stringify(d, null, 2);
476	              const truncated = s && s.length > 2000 ? s.slice(0, 2000) + "...(truncated)" : s;
477	              return "  [" + i + "]: " + truncated;
478	            } catch { return "  [" + i + "]: " + String(d); }
479	          }).join("\n");
480	          userMessage += "\n\nPREVIOUS INPUT VALUES:\n" + prevDesc;
481	        }
482	
483	        const conversationMessages: any[] = [{ role: "user", content: userMessage }];
484	        const extras = {
485	          tools: apiTools,
486	          tool_choice: { type: "auto" as const },
487	          _source: "reasoning:" + (componentId || "anonymous"),
488	        };
489	
490	        // Multi-turn agent loop.
491	        // Terminates when: (1) __reshape called, (2) no tool calls, (3) maxTurns.
492	        // respond is non-terminal — it writes to the response slot, loop continues.
493	
494	        for (let turn = 0; turn < maxTurns; turn++) {
495	          const turnLabel = maxTurns > 1 ? " (turn " + (turn + 1) + "/" + maxTurns + ")" : "";
496	          update({ turn: turn + 1, statusText: turn === 0 ? "Thinking..." : "Reasoning..." + turnLabel });
497	
498	          const response = await runtime.callLLM(system, conversationMessages, extras);
499	
500	          if (!mountedRef.current) return;
501	
502	          if (response.error) {
503	            update({ status: "error", error: "Reasoning error: " + response.error, statusText: null });
504	            return;
505	          }
506	
507	          const data = response.data;
508	          const contentBlocks = data?.content || [];
509	
510	          // Gather all tool_use blocks
511	          const allToolBlocks = contentBlocks.filter((b: any) => b.type === "tool_use");
512	
513	          // Check for __reshape — TERMINAL (component will be replaced)
514	          const reshapeBlock = allToolBlocks.find((b: any) => b.name === "__reshape");
515	          if (reshapeBlock?.input) {
516	            update({ statusText: "Reshaping..." });
517	            // Process sibling tool calls (including respond) before terminating
518	            for (const tb of allToolBlocks) {
519	              if (tb.name === "respond") {
520	                latestResponse = tb.input as T;
521	              } else if (tb.name !== "__reshape") {
522	                try { await Promise.resolve(dispatchTool(tb.name, tb.input)); } catch {}
523	              }
524	            }
525	            dispatchTool("__reshape", reshapeBlock.input);
526	            // Component is being replaced — set final state
527	            update({ status: "done", response: latestResponse, statusText: null });
528	            return;
529	          }
530	
531	          // No tool calls — agent is done, loop ends naturally
532	          if (allToolBlocks.length === 0) {
533	            // If agent never called respond, extract text as fallback content
534	            if (!latestResponse) {
535	              const text = contentBlocks.find((b: any) => b.type === "text")?.text || "";
536	              if (text) latestResponse = { content: text } as any;
537	            }
538	            break;
539	          }
540	
541	          // Process all tool calls in this turn (including respond)
542	          const toolResultBlocks: any[] = [];
543	          for (const tb of allToolBlocks) {
544	            // respond — capture response, non-terminal
545	            if (tb.name === "respond") {
546	              latestResponse = tb.input as T;
547	              update({ response: latestResponse, statusText: "Response ready" + turnLabel });
548	              toolResultBlocks.push({
549	                type: "tool_result",
550	                tool_use_id: tb.id,
551	                content: "Response received.",
552	              });
553	              continue;
554	            }
555	
556	            // Update statusText with tool being called
557	            update({ statusText: "Calling " + tb.name + "..." + turnLabel });
558	
559	            try {
560	              const res = await Promise.resolve(dispatchTool(tb.name, tb.input));
561	              toolResultBlocks.push({
562	                type: "tool_result",
563	                tool_use_id: tb.id,
564	                content: res !== undefined ? (typeof res === "string" ? res : JSON.stringify(res)) : "done",
565	              });
566	            } catch (e: any) {
567	              toolResultBlocks.push({
568	                type: "tool_result",
569	                tool_use_id: tb.id,
570	                content: "Error: " + (e.message || String(e)),
571	                is_error: true,
572	              });
573	            }
574	          }
575	
576	          // Last allowed turn — don't loop back
577	          if (turn >= maxTurns - 1) break;
578	
579	          // Feed results back for next turn
580	          conversationMessages.push({ role: "assistant", content: contentBlocks });
581	          conversationMessages.push({ role: "user", content: toolResultBlocks });
582	        }
583	
584	        update({ status: "done", response: latestResponse, statusText: null });
585	      } catch (err: any) {
586	        if (mountedRef.current) {
587	          update({ status: "error", error: "Reasoning error: " + (err.message || String(err)), statusText: null });
588	        }
589	      }
590	    };
591	
592	    // Debounce — default 300ms so text-input-driven deps don't fire per-keystroke
593	    const delay = optionsRef.current.debounceMs ?? 300;
594	    if (delay > 0) {
595	      if (debounceRef.current) clearTimeout(debounceRef.current);
596	      debounceRef.current = setTimeout(doReason, delay);
597	    } else {
598	      doReason();
599	    }
600	
601	    return () => {
602	      if (debounceRef.current) clearTimeout(debounceRef.current);
603	    };
604	  }, deps); // eslint-disable-line react-hooks/exhaustive-deps
605	
606	  return state;
607	}
