30	function getMutationHistory(): MutationEntry[] {
31	  const w = window as any;
32	  if (!w.__MUTATIONS__) w.__MUTATIONS__ = [];
33	  return w.__MUTATIONS__;
34	}
35	
36	function recordMutation(entry: Omit<MutationEntry, "id" | "timestamp">): void {
37	  const history = getMutationHistory();
38	  history.push({
39	    ...entry,
40	    id: Math.random().toString(36).slice(2, 10),
41	    timestamp: Date.now(),
42	  });
43	  // Keep at most 50 entries to avoid unbounded growth
44	  if (history.length > 50) history.splice(0, history.length - 50);
45	}
46	
47	function getPreviousSource(componentId: string): string | null {
48	  const history = getMutationHistory();
49	  for (let i = history.length - 1; i >= 0; i--) {
50	    if (history[i].componentId === componentId && history[i].previousSource) {
51	      return history[i].previousSource;
52	    }
53	  }
54	  return null;
55	}
