67	// ---- Error Boundary ----
68	
69	interface EBProps {
70	  componentId: string;
71	  children?: ReactNode;
72	  onCrash: (error: Error, crashCount: number) => void;
73	}
74	
75	interface EBState {
76	  hasError: boolean;
77	  error: Error | null;
78	  crashCount: number;
79	  rollingBack: boolean;
80	}
81	
82	class ComponentErrorBoundary extends Component<EBProps, EBState> {
83	  state: EBState = { hasError: false, error: null, crashCount: 0, rollingBack: false };
84	
85	  static getDerivedStateFromError(error: Error): Partial<EBState> {
86	    return { hasError: true, error };
87	  }
88	
89	  componentDidCatch(error: Error) {
90	    const next = this.state.crashCount + 1;
91	    this.setState({ crashCount: next });
92	    console.error("[AC:" + this.props.componentId + "] Crash #" + next, error);
93	    this.props.onCrash(error, next);
94	  }
95	
96	  reset = () => {
97	    this.setState({ hasError: false, error: null });
98	  };
99	
100	  render() {
101	    if (this.state.hasError) {
102	      const { error, crashCount } = this.state;
103	      return (
104	        <div style={{
105	          padding: "20px", margin: "10px", border: "1px solid #c00",
106	          borderRadius: "8px", background: "#1a0000", color: "#f88",
107	          fontFamily: "monospace", fontSize: "13px",
108	        }}>
109	          <div style={{ fontWeight: "bold", marginBottom: "8px" }}>
110	            Component error [{this.props.componentId}] (crash #{crashCount})
111	          </div>
112	          <pre style={{ whiteSpace: "pre-wrap", color: "#faa", margin: "8px 0" }}>
113	            {error?.message || "Unknown error"}
114	          </pre>
115	          {crashCount >= 3 && (
116	            <div style={{ color: "#fa0", marginBottom: "8px" }}>
117	              Multiple crashes detected. Attempting rollback to last known-good source...
118	            </div>
119	          )}
120	          <button
121	            onClick={this.reset}
122	            style={{
123	              padding: "6px 16px", background: "#333", color: "#fff",
124	              border: "1px solid #666", borderRadius: "4px", cursor: "pointer",
125	            }}
126	          >
127	            Retry
128	          </button>
129	        </div>
130	      );
131	    }
132	    return this.props.children;
133	  }
134	}
