136	// ---- Shape comparison ----
137	// Tracks key names + value types for precise structural change detection.
138	
139	function getShape(obj: Record<string, any> | undefined): string {
140	  if (!obj) return "";
141	  return Object.keys(obj).sort().map(k => {
142	    const v = obj[k];
143	    const t = v === null ? "null" : Array.isArray(v) ? "array" : typeof v;
144	    return k + ":" + t;
145	  }).join(",");
146	}
147	
148	function getToolShape(tools: any[] | undefined): string {
149	  if (!tools) return "";
150	  return tools.map((t: any) => {
151	    const sk = t.schema ? Object.keys(t.schema).sort().join("+") : "";
152	    return t.name + (sk ? "(" + sk + ")" : "");
153	  }).sort().join(",");
154	}
155	
156	function getHandlerShape(handlers: Record<string, any> | undefined): string {
157	  if (!handlers) return "";
158	  return Object.keys(handlers).sort().join(",");
159	}
160	
161	// ---- Freshness tracking ----
162	// Tracks reshape requests per component to detect stale authoring.
163	
164	const reshapeCounters: Record<string, { count: number; since: number }> = {};
165	
166	function trackReshape(componentId: string): void {
167	  const entry = reshapeCounters[componentId] ||= { count: 0, since: Date.now() };
168	  entry.count++;
169	  if (entry.count >= 3) {
170	    console.warn("[AC:" + componentId + "] Frequent reshape requests (" + entry.count + " since last authoring). Consider revising guidelines.");
171	  }
172	}
173	
174	function resetReshapeCounter(componentId: string): void {
175	  reshapeCounters[componentId] = { count: 0, since: Date.now() };
176	}
177	
178	// ---- AbstractComponent ----
179	
180	export function AbstractComponent({
181	  id,
182	  inputs = {},
183	  tools = [],
184	  handlers = {},
185	  guidelines,
186	  fallback,
187	}: {
188	  id: string;
189	  inputs?: Record<string, any>;
190	  tools?: Array<{ name: string; description: string; schema?: Record<string, string>; handler: (args: any) => any }>;
191	  handlers?: Record<string, { description: string; fn: (...args: any[]) => any }>;
192	  guidelines?: string;
193	  fallback?: ReactNode;
194	}) {
195	  const { runtime: ctxRuntime } = useRuntimeContext();
196	
197	  const [phase, setPhase] = useState<"checking" | "authoring" | "ready" | "error">("checking");
198	  const [errorMsg, setErrorMsg] = useState("");
199	  const [reshapeVersion, setReshapeVersion] = useState(0);
200	  const authoringRef = useRef(false);
201	  const shapeRef = useRef({ inputs: getShape(inputs), tools: getToolShape(tools), handlers: getHandlerShape(handlers) });
202	
203	  // Get the compiled component from the registry
204	  const registry = (window as any).__COMPONENTS__ || {};
205	  const compiledComponent = registry[id] || null;
206	
207	  // Check if shape changed (triggers re-authoring)
208	  const currentInputShape = getShape(inputs);
209	  const currentToolShape = getToolShape(tools);
210	  const currentHandlerShape = getHandlerShape(handlers);
211	  const shapeChanged =
212	    phase === "ready" &&
213	    (currentInputShape !== shapeRef.current.inputs ||
214	     currentToolShape !== shapeRef.current.tools ||
215	     currentHandlerShape !== shapeRef.current.handlers);
216	
217	  // ---- Tool Context: parent tools injected into useReasoning via context ----
218	
219	  // Strip handlers to get tool definitions for the LLM prompt
220	  const toolDefsKey = getToolShape(tools);
221	  const toolDefs = useMemo(() =>
222	    tools.map(t => ({ name: t.name, description: t.description, schema: t.schema })),
223	    [toolDefsKey]
224	  );
225	
226	  // Stable dispatch via ref so context value doesn't churn
227	  const toolsRef = useRef(tools);
228	  toolsRef.current = tools;
229	
230	  const dispatch = useCallback((name: string, args: any): any => {
231	    const tool = toolsRef.current.find(t => t.name === name);
232	    if (tool?.handler) return tool.handler(args);
233	    console.warn("[AC:" + id + "] No handler for tool: " + name);
234	    return undefined;
235	  }, [id]);
236	
237	  const reshape = useCallback((reason: string) => {
238	    trackReshape(id);
239	    const runtime = ctxRuntime;
240	    if (runtime) {
241	      const vfsPath = "/src/ac/" + id + ".tsx";
242	      const currentSource = runtime.files.get(vfsPath) || "";
243	      if (currentSource) {
244	        recordMutation({
245	          componentId: id,
246	          trigger: "reshape:" + reason,
247	          previousSource: currentSource,
248	          newSource: "",
249	          outcome: "swap",
250	        });
251	      }
252	    }
253	    // Bump version to force the authoring effect to re-fire.
254	    // shapeRef reset ensures isReauthor detects existing source.
255	    shapeRef.current = { inputs: "", tools: "", handlers: "" };
256	    setReshapeVersion(v => v + 1);
257	    setPhase("checking");
258	  }, [id]);
259	
260	  const toolCtxValue = useMemo(() => ({
261	    tools: toolDefs,
262	    dispatch,
263	    reshape,
264	    componentId: id,
265	  }), [toolDefs, dispatch, reshape, id]);
266	
267	  // ---- Strip handler descriptions for child (just the functions) ----
268	
269	  const handlersRef = useRef(handlers);
270	  handlersRef.current = handlers;
271	
272	  const handlerFns = useMemo(() => {
273	    const result: Record<string, (...args: any[]) => any> = {};
274	    for (const k of Object.keys(handlers)) {
275	      // Stable wrappers that read from ref
276	      result[k] = (...args: any[]) => handlersRef.current[k]?.fn(...args);
277	    }
278	    return result;
279	  }, [getHandlerShape(handlers)]);
280	
281	  // ---- Author or re-author when needed ----
282	
283	  useEffect(() => {
284	    if (authoringRef.current) return;
285	
286	    // Reshape request: phase is "checking", reshapeVersion > 0 (not initial mount),
287	    // and we already have a compiled component → reshape() was called.
288	    const reshapeRequested = phase === "checking" && reshapeVersion > 0 && !!compiledComponent;
289	
290	    // Already have the component, no shape change, and no reshape request
291	    if (compiledComponent && !shapeChanged && !reshapeRequested) {
292	      shapeRef.current = { inputs: currentInputShape, tools: currentToolShape, handlers: currentHandlerShape };
293	      setPhase("ready");
294	      return;
295	    }
296	
297	    // Need to author (or re-author)
298	    const runtime = ctxRuntime;
299	    if (!runtime) {
300	      setPhase("error");
301	      setErrorMsg("No runtime available");
302	      return;
303	    }
304	
305	    authoringRef.current = true;
306	    setPhase("authoring");
307	
308	    // LLM calls can run in parallel, but buildAndRun must be serialised.
309	    (async () => {
310	      try {
311	        const vfsPath = "/src/ac/" + id + ".tsx";
312	        const existingSource = runtime.files.get(vfsPath) || "";
313	        const isReauthor = (shapeChanged || reshapeRequested) && !!existingSource;
314	
315	        // Build handler descriptions for the authoring prompt
316	        const handlerDescs: Record<string, string> = {};
317	        for (const [k, v] of Object.entries(handlers)) {
318	          handlerDescs[k] = v.description;
319	        }
320	
321	        // Call LLM to author the component via write_component tool
322	        const system = runtime.buildAuthoringPrompt(id, inputs, toolDefs, handlerDescs, guidelines, isReauthor ? existingSource : undefined);
323	        const messages = [{ role: "user", content: "Author this component." }];
324	        const authorTool = {
325	          name: "write_component",
326	          description: "Write the complete component source code",
327	          input_schema: {
328	            type: "object",
329	            properties: {
330	              src: { type: "string", description: "Complete TSX source code for the component" },
331	            },
332	            required: ["src"],
333	          },
334	        };
335	        const response = await runtime.callLLM(system, messages, {
336	          tools: [authorTool],
337	          tool_choice: { type: "tool", name: "write_component" },
338	          _source: "author:" + id,
339	        });
340	
341	        if (response.error) {
342	          setPhase("error");
343	          setErrorMsg(response.error);
344	          authoringRef.current = false;
345	          return;
346	        }
347	
348	        // Extract source from write_component tool_use block
349	        const data = response.data;
350	        const toolBlock = data?.content?.find(
351	          (b: any) => b.type === "tool_use" && b.name === "write_component"
352	        );
353	        let source = (toolBlock?.input?.src || "").trim();
354	
355	        if (!source) {
356	          setPhase("error");
357	          setErrorMsg("Authoring produced empty source");
358	          authoringRef.current = false;
359	          return;
360	        }
361	
362	        // Serialise VFS write + rebuild to prevent concurrent builds
363	        await enqueueAuthoring(async () => {
364	          recordMutation({
365	            componentId: id,
366	            trigger: isReauthor ? "re-author:shape-change" : "author:first-mount",
367	            previousSource: existingSource,
368	            newSource: source,
369	            outcome: "swap",
370	          });
371	
372	          runtime.files.set(vfsPath, source);
373	          await runtime.idb.put(vfsPath, source);
374	          runtime.regenerateRegistry();
375	          await runtime.buildAndRun("author:" + id);
376	        });
377	
378	        shapeRef.current = { inputs: currentInputShape, tools: currentToolShape, handlers: currentHandlerShape };
379	        resetReshapeCounter(id);
380	        setPhase("ready");
381	      } catch (err: any) {
382	        setPhase("error");
383	        setErrorMsg(err.message || String(err));
384	      } finally {
385	        authoringRef.current = false;
386	      }
387	    })();
388	  }, [id, ctxRuntime, compiledComponent, shapeChanged, reshapeVersion, phase, currentInputShape, currentToolShape, currentHandlerShape]);
389	
390	  // Error boundary crash handler with rollback on repeated crashes
391	  const handleCrash = useCallback((error: Error, crashCount: number) => {
392	    console.error("[AC:" + id + "] Component crashed:", error.message);
393	
394	    if (crashCount >= 3) {
395	      const prev = getPreviousSource(id);
396	      if (prev) {
397	        const runtime = ctxRuntime;
398	        if (runtime) {
399	          const vfsPath = "/src/ac/" + id + ".tsx";
400	          const currentSource = runtime.files.get(vfsPath) || "";
401	
402	          console.warn("[AC:" + id + "] Rolling back to previous source after " + crashCount + " crashes");
403	
404	          recordMutation({
405	            componentId: id,
406	            trigger: "rollback:crash-count-" + crashCount,
407	            previousSource: currentSource,
408	            newSource: prev,
409	            outcome: "rollback",
410	          });
411	
412	          runtime.files.set(vfsPath, prev);
413	          runtime.idb.put(vfsPath, prev).catch(() => {});
414	          runtime.regenerateRegistry();
415	          runtime.buildAndRun("rollback:" + id).catch((e: any) => {
416	            console.error("[AC:" + id + "] Rollback build failed:", e);
417	          });
418	        }
419	      } else {
420	        console.warn("[AC:" + id + "] No previous source available for rollback");
421	      }
422	    }
423	  }, [id]);
424	
425	  // Render states
426	  if (phase === "error") {
427	    return (
428	      <div style={{
429	        padding: "20px", margin: "10px", border: "1px solid #c00",
430	        borderRadius: "8px", background: "#1a0000", color: "#f88",
431	        fontFamily: "monospace", fontSize: "13px",
432	      }}>
433	        <div style={{ fontWeight: "bold", marginBottom: "8px" }}>
434	          Authoring failed [{id}]
435	        </div>
436	        <pre style={{ whiteSpace: "pre-wrap", color: "#faa" }}>{errorMsg}</pre>
437	        <button
438	          onClick={() => { setPhase("checking"); setErrorMsg(""); }}
439	          style={{
440	            marginTop: "8px", padding: "6px 16px", background: "#333",
441	            color: "#fff", border: "1px solid #666", borderRadius: "4px", cursor: "pointer",
442	          }}
443	        >
444	          Retry
445	        </button>
446	      </div>
447	    );
448	  }
449	
450	  if (phase === "authoring" || phase === "checking" || !compiledComponent) {
451	    return fallback || (
452	      <div style={{
453	        padding: "40px", textAlign: "center", color: "#888",
454	        fontFamily: "system-ui", fontSize: "14px",
455	      }}>
456	        <div style={{
457	          display: "inline-block", width: "20px", height: "20px",
458	          border: "2px solid #444", borderTopColor: "#888",
459	          borderRadius: "50%", animation: "spin 0.8s linear infinite",
460	        }} />
461	        <div style={{ marginTop: "12px" }}>
462	          {phase === "authoring" ? "Authoring " + id + "..." : "Loading..."}
463	        </div>
464	        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
465	      </div>
466	    );
467	  }
468	
469	  // Render the authored component wrapped in ToolContext
470	  return (
471	    <ComponentErrorBoundary componentId={id} onCrash={handleCrash}>
472	      <ToolContext.Provider value={toolCtxValue}>
473	        {React.createElement(compiledComponent, { inputs, handlers: handlerFns })}
474	      </ToolContext.Provider>
475	    </ComponentErrorBoundary>
476	  );
477	}
